            if (hq_PlanBath_sel1 == 1)
            {
                int tub = hq_PlanBath_tub;
                int first = hq_PlanBath_first;
                if (tub >= 0 && !Keep(first, false)) tub = -1;
                hq_PlanBath_tub = tub;
                hq_PlanBath_first = first;
            }
        }
        if (Ph(3))
        {
            int dx = hq_PlanBath_dx;
            int dz = hq_PlanBath_dz;
            uint[] r2 = SR(2);
            int first2 = nEmit;
            int toilet = WallPlace(Dn("k_toilet"), WM_FAR, dx, dz, WIN_ANY, EF_MANDATORY, r2);
            hq_PlanBath_dx = dx;
            hq_PlanBath_dz = dz;
            hq_PlanBath_r2 = r2;
            hq_PlanBath_first2 = first2;
            hq_PlanBath_toilet = toilet;
        }
        if (Ph(4))
        {
            int first2 = hq_PlanBath_first2;
            int toilet = hq_PlanBath_toilet;
            if (toilet >= 0 && !Keep(first2, true)) toilet = -1;
            if (toilet < 0) MandFail(1);
            int sink = -1;
            first2 = nEmit;
            hq_PlanBath_first2 = first2;
            hq_PlanBath_toilet = toilet;
            hq_PlanBath_sink = sink;
        }
        if (Ph(5))
        {
            int dx = hq_PlanBath_dx;
            int dz = hq_PlanBath_dz;
            uint[] r2 = hq_PlanBath_r2;
            int toilet = hq_PlanBath_toilet;
            int sink = hq_PlanBath_sink;
            if (toilet >= 0) sink = RelBeside(Dn("k_bathSink"), toilet, 0, 320, EF_MANDATORY, r2);
            if (sink < 0) sink = WallPlace(Dn("k_bathSink"), WM_NEAR, toilet >= 0 ? emitX[toilet] : dx, toilet >= 0 ? emitZ[toilet] : dz, WIN_ANY, EF_MANDATORY, r2);
            hq_PlanBath_dx = dx;
            hq_PlanBath_dz = dz;
            hq_PlanBath_r2 = r2;
            hq_PlanBath_toilet = toilet;
            hq_PlanBath_sink = sink;
        }
        if (Ph(6))
        {
            int first2 = hq_PlanBath_first2;
            int sink = hq_PlanBath_sink;
            if (sink >= 0 && !Keep(first2, true)) sink = -1;
            if (sink < 0) MandFail(1);
            // (c) the bin beside the toilet, a mat in front of the bath or the basin
            uint[] r3 = SR(3);
            hq_PlanBath_first2 = first2;
            hq_PlanBath_sink = sink;
            hq_PlanBath_r3 = r3;
        }
        if (Ph(7))
        {
            int toilet = hq_PlanBath_toilet;
            uint[] r3 = hq_PlanBath_r3;
            if (toilet >= 0 && RngChance(r3, 750) && Fit(1))
            {
                int first = nEmit;
                if (RelBeside(Dn("k_trashcan"), toilet, 0, 130, 0, r3) >= 0) Keep(first, false);
            }
            uint[] r4 = SR(4);
            hq_PlanBath_toilet = toilet;
            hq_PlanBath_r3 = r3;
            hq_PlanBath_r4 = r4;
        }
        if (Ph(8))
        {
            int tub = hq_PlanBath_tub;
            int sink = hq_PlanBath_sink;
            uint[] r4 = hq_PlanBath_r4;
            if (RngChance(r4, 700) && Fit(1))
            {
                int mat = Dn("k_doormat"), host = tub >= 0 ? tub : sink;
                if (host >= 0) RelFlat(mat, host, 0, Sz(emitDef[host]) / 2 + 80 + Sz(mat) / 2, 0, 0);
            }
            // the laundry corner: washer, perhaps a dryer beside it, the basket
            uint[] r5 = SR(5);
            hq_PlanBath_sel2 = 0;
            if (RngChance(r5, 600) && Fit(1)) hq_PlanBath_sel2 = 1;
            hq_PlanBath_tub = tub;
            hq_PlanBath_sink = sink;
            hq_PlanBath_r4 = r4;
            hq_PlanBath_r5 = r5;
        }
        if (Ph(9))
        {
            if (hq_PlanBath_sel2 == 1)
            {
                uint[] r5 = hq_PlanBath_r5;
                int first = nEmit;
                int washer = WallPlace(Dn("k_washer"), WM_CORNER, 0, 0, WIN_ANY, 0, r5);
                hq_PlanBath_r5 = r5;
                hq_PlanBath_first = first;
                hq_PlanBath_washer = washer;
            }
        }
        if (Ph(10))
        {
            if (hq_PlanBath_sel2 == 1)
            {
                int first = hq_PlanBath_first;
                int washer = hq_PlanBath_washer;
                hq_PlanBath_sel3 = 0;
                if (washer >= 0 && Keep(first, false)) hq_PlanBath_sel3 = 1;
                hq_PlanBath_first = first;
                hq_PlanBath_washer = washer;
            }
        }
        if (Ph(11))
        {
            if (hq_PlanBath_sel2 == 1 && hq_PlanBath_sel3 == 1)
            {
                uint[] r5 = hq_PlanBath_r5;
                int first = hq_PlanBath_first;
                int washer = hq_PlanBath_washer;
                int side = RngChance(r5, 500) ? 1 : -1;
                if (RngChance(r5, 450) && Fit(1))
                {
                    first = nEmit;
                    if (RelBeside(Dn("k_dryer"), washer, side, 20, 0, r5) >= 0) Keep(first, false);
                }
                hq_PlanBath_r5 = r5;
                hq_PlanBath_first = first;
                hq_PlanBath_washer = washer;
                hq_PlanBath_side = side;
            }
        }
        if (Ph(12))
        {
            if (hq_PlanBath_sel2 == 1 && hq_PlanBath_sel3 == 1)
            {
                uint[] r5 = hq_PlanBath_r5;
                int first = hq_PlanBath_first;
                int washer = hq_PlanBath_washer;
                int side = hq_PlanBath_side;
                if (RngChance(r5, 650) && Fit(1))
                {
                    first = nEmit;
                    if (RelBeside(Dn("gen_laundryBasket"), washer, -side, 60, 0, r5) >= 0) Keep(first, false);
                }
                hq_PlanBath_r5 = r5;
                hq_PlanBath_first = first;
                hq_PlanBath_washer = washer;
                hq_PlanBath_side = side;
            }
        }
        if (Ph(13))
        {
            int dx = hq_PlanBath_dx;
            int dz = hq_PlanBath_dz;
            int sink = hq_PlanBath_sink;
            uint[] r6 = SR(6);
            if (RngChance(r6, 600) && Fit(1))
            {
                int first = nEmit;
                if (WallPlace(Dn("q_cabinetSmall"), WM_NEAR, sink >= 0 ? emitX[sink] : dx, sink >= 0 ? emitZ[sink] : dz, WIN_ANY, 0, r6) >= 0) Keep(first, false);
            }
            hq_PlanBath_dx = dx;
            hq_PlanBath_dz = dz;
            hq_PlanBath_sink = sink;
        }
        if (PhLoop(14, 100000))
        {
            if (planIter == 0) { hq_Extras_k0 = 20; hq_Extras_chance = 400; hq_Extras_items = new string[] { "ck_plant", "wk_trashcan" }; PhSubReset(); }
            PhPush(); Extras_Body(); bool fin = PhAdvance(); PhPop();
            if (fin) {  PhBreak(); }
        }
        if (Ph(15))
        {
            // (e) the cleaning corner by the door: a bucket with a mop or a broom
            uint[] r8 = SR(8);
            hq_PlanBath_sel4 = 0;
            if (RngChance(r8, 330) && LooseFit(2)) hq_PlanBath_sel4 = 1;
            hq_PlanBath_r8 = r8;
        }
        if (Ph(16))
        {
            if (hq_PlanBath_sel4 == 1)
            {
                uint[] r8 = hq_PlanBath_r8;
                int first = nEmit;
                FSet(Pick(r8, "gen_mop", 5, "gen_broom", 5), Pick(r8, "s_bucket", 5, "t_bucketMetal", 5));
                hq_PlanBath_r8 = r8;
                hq_PlanBath_first = first;
            }
        }
        if (Ph(17))
        {
            if (hq_PlanBath_sel4 == 1)
            {
                int dx = hq_PlanBath_dx;
                int dz = hq_PlanBath_dz;
                uint[] r8 = hq_PlanBath_r8;
                int first = hq_PlanBath_first;
                if (FormAt(GenData.GL_ROW, 70, GenData.A_WALL, WM_NEAR, dx, dz, 0, r8) >= 0 && Keep(first, false)) MarkLoose(first);
                hq_PlanBath_dx = dx;
                hq_PlanBath_dz = dz;
                hq_PlanBath_r8 = r8;
                hq_PlanBath_first = first;
            }
        }
    }

